      "label": "not_assessable",
      "reason": "Der er ikke angivet nogen kilde, så støtten til påstandene kan ikke bedømmes."
    },
    "c07_no_unsupported_legal_additions": {
      "label": "met",
      "reason": "Alle materielle udsagn findes i vejledningens afsnit 5.1.2: lægeattest, indhold, fremmøde som udgangspunkt, journaloplysninger i særlige tilfælde og udgifter hos styrelsen. Svaret tilføjer ingen regel uden støtte."
    },
    "c08_qualifications_and_exceptions": {
      "label": "met",
      "reason": "Svaret bruger 'kan' for attestindhentningen og dermed ikke som automatisk pligt. 'I særlige tilfælde' bevares for journaloplysningerne, og 'som udgangspunkt' bevares for fremmøde."
    },
    "c09_reasoning_coherence": {
      "label": "met",
      "reason": "Svaret er internt sammenhængende. Først kommer muligheden for at indhente en attest, derefter attestens indhold og de supplerende forhold. Der er ingen modsigelser."
    },
    "c10_legal_modality_precision": {
      "label": "met",
      "reason": "'Kan' for indhentning og journaloplysninger, 'skal' for attestens indhold og 'som udgangspunkt' for fremmøde svarer til vejledningens modalitet. Svaret gør ikke skønsmæssige elementer absolutte."
    }
  },
  "xhaile_coverage": {
    "A61": {
      "label": "yes",
      "reason": "Svaret dækker alle led i punktet: muligheden for at indhente lægeattest, attestens indhold, fremmøde som udgangspunkt, yderligere journaloplysninger i særlige tilfælde og udgifter afholdt af styrelsen. Svaret nævner ikke udtrykkeligt, at ansøgeren skal medvirke, men siger, at ansøgeren som udgangspunkt skal møde op."
    }
  },
  "overall_notes": "Indholdet er juridisk korrekt og fuldstændigt i forhold til rubrikken og vejledningen. Svaret nævner ingen kilde, så C04 er not_met, og C05 og C06 er not_assessable efter kilderegelen."
